{
  "script": "Hangul",
  "title": "Your First Hangul: Vowels and Consonants",
  "description": "Read simple Korean syllable blocks such as ga, na, da, go, no, and do.",
  "canDo": "Read and say ㅏ, ㅓ, ㅗ, ㅜ, ㅡ, ㅣ, ㄱ, ㄴ, and ㄷ in simple syllable blocks.",
  "intro": [
    {
      "title": "Read in blocks",
      "text": "Read Korean from left to right. Each block is a syllable built from a consonant and a vowel, like 가 (ga) and 나 (na)."
    },
    {
      "title": "Notice where the vowel sits",
      "text": "A vertical vowel such as ㅏ (a) sits to the right of its consonant; a horizontal vowel such as ㅗ (o) sits underneath. Korean vowels are short and pure, without the extra glide often heard in English vowels."
    }
  ],
  "letters": [
    {
      "symbol": "ㅏ",
      "readingAid": "a",
      "pronunciation": "Like the vowel in “father,” short and pure. You’ll hear it in 아.",
      "audioText": "아",
      "forms": []
    },
    {
